.ds {
  --ds-base-text:var(--p-ink,#2c333d);
  --ds-base-bg:var(--p-bg,#ffffff);
  --ds-base-text-md:var(--p-text-md,16px);
  --ds-base-font:var(--p-font,Pretendard, sans-serif);
  --ds-base-focus:var(--p-highlight,#6153b5);
  --ds-base-text-sm:var(--p-text-sm,13px);
  --ds-base-space-3:var(--p-space-sm,12px);
  --ds-base-muted:var(--p-muted,#59636f);
  --ds-base-border:var(--p-line,#c2cad5);
  --ds-base-radius:var(--p-radius,24px);
  --ds-base-surface:var(--p-surface,#f1f3f6);
  --ds-base-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-base-edge:var(--p-edge,#ffffff);
  --ds-base-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-base-high:var(--p-high,#fafbfc);
  --ds-base-glass-shadow:var(--p-glass-shadow,0 8px 24px #38465e12);
  --ds-base-glass:var(--p-glass,#f6f8fbe8);
}
.ds {
  color:var(--ds-base-text); background:var(--ds-base-bg); font:var(--ds-base-text-md)/1.5 var(--ds-base-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-base-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-base-text-sm); margin-top:var(--ds-base-space-3); min-height:20px; color:var(--ds-base-muted); }
.ds .ds-surface { border:1px solid var(--ds-base-border); border-radius:var(--ds-base-radius); background:var(--ds-base-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-base-shadow); border-color:var(--ds-base-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-base-inset); background:var(--ds-base-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-base-high); box-shadow:var(--ds-base-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-base-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-base-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds {
  --ds-selection-space-6:var(--p-space-lg,24px);
  --ds-selection-space-3:var(--p-space-sm,12px);
  --ds-selection-control-border:var(--p-control-border,#7b8592);
  --ds-selection-bg:var(--p-bg,#ffffff);
  --ds-selection-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-selection-accent:var(--p-accent,#303b48);
  --ds-selection-on-accent:var(--p-on-accent,#ffffff);
  --ds-selection-muted:var(--p-muted,#59636f);
  --ds-selection-disabled:var(--p-disabled,#dce1e8);
  --ds-selection-border:var(--p-line,#c2cad5);
  --ds-selection-knob-shadow:var(--p-knob-shadow,0 1px 3px #26344726);
  --ds-selection-duration:var(--p-duration,140ms);
  --ds-selection-control-radius:var(--p-control-radius,16px);
  --ds-selection-high:var(--p-high,#fafbfc);
  --ds-selection-space-2:var(--p-space-xs,8px);
  --ds-selection-focus:var(--p-highlight,#6153b5);
}
.ds .ds-choices { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,170px),1fr)); gap:var(--ds-selection-space-6); }
.ds .ds-choices fieldset,.ds .ds-radio-group { border:0; padding:0; min-width:0; }
.ds .ds-choices legend,.ds .ds-radio-group legend { font-size:14px; font-weight:600; margin-bottom:var(--ds-selection-space-3); padding:0; }
.ds .ds-choice { display:flex; align-items:center; gap:var(--ds-selection-space-3); min-height:44px; width:fit-content; padding-inline:4px; cursor:pointer; font-size:14px; }
.ds .ds-choice input { appearance:none; position:relative; margin:0; width:22px; height:22px; border:1.5px solid var(--ds-selection-control-border); border-radius:7px; background:var(--ds-selection-bg); box-shadow:var(--ds-selection-inset); cursor:inherit; flex-shrink:0; }
.ds .ds-choice input:checked,.ds .ds-choice input:indeterminate { background:var(--ds-selection-accent); border-color:var(--ds-selection-accent); box-shadow:none; }
.ds .ds-choice input[type="checkbox"]:checked::after { content:''; position:absolute; width:6px; height:10px; left:6px; top:2px; border:solid var(--ds-selection-on-accent); border-width:0 2px 2px 0; transform:rotate(45deg); }
.ds .ds-choice input:indeterminate::after { content:''; position:absolute; width:10px; height:2px; left:4px; top:8px; background:var(--ds-selection-on-accent); transform:none; border:0; }
.ds .ds-choice input[type="radio"] { border-radius:50%; }
.ds .ds-choice input[type="radio"]:checked::after { content:''; position:absolute; inset:5px; background:var(--ds-selection-on-accent); border-radius:50%; }
.ds .ds-choice:has(:disabled) { color:var(--ds-selection-muted); cursor:not-allowed; }
.ds .ds-choice input:disabled { opacity:1; background:var(--ds-selection-disabled); border-color:var(--ds-selection-border); box-shadow:none; }
.ds .ds-choice input:disabled::after { border-color:var(--ds-selection-muted); }
.ds .ds-choice input[type="radio"]:disabled::after { background:var(--ds-selection-muted); }
.ds .ds-choice .ds-switch { width:44px; height:26px; border-radius:24px; }
.ds .ds-switch::before { content:''; position:absolute; top:3px; left:3px; width:18px; height:18px; border-radius:50%; background:var(--ds-selection-muted); box-shadow:var(--ds-selection-knob-shadow); transition:left var(--ds-selection-duration); }
.ds .ds-choice input.ds-switch:checked::after { content:none; }
.ds .ds-switch:checked::before { left:21px; background:var(--ds-selection-on-accent); }
.ds .ds-switch:disabled::before { background:var(--ds-selection-muted); box-shadow:none; }
@media(forced-colors:active) {
  .ds .ds-choice input:not(.ds-switch) { appearance:auto; }
  .ds .ds-choice input:not(.ds-switch)::after { display:none; }
  .ds .ds-switch { border-color:ButtonText; }
  .ds .ds-switch::before { background:ButtonText; }
  .ds .ds-switch:checked { background:Highlight; }
  .ds .ds-switch:checked::before { background:HighlightText; }
}
/* looks: checkbox, radio and switch share the label hook .ds-choice[data-look]; checked keeps a mark or a moved thumb, never color alone */
.ds .ds-choice[data-look="card"] { min-width:200px; min-height:56px; padding:12px 16px; border:1px solid var(--ds-selection-border); border-radius:var(--ds-selection-control-radius); background:var(--ds-selection-bg); }
.ds .ds-choice[data-look="card"]:has(:checked) { border-color:var(--ds-selection-accent); box-shadow:inset 0 0 0 1px var(--ds-selection-accent); background:var(--ds-selection-high); font-weight:600; }
.ds .ds-radio-group:has(> .ds-choice[data-look="card"]) .ds-choice + .ds-choice { margin-top:var(--ds-selection-space-2); }
.ds .ds-choice[data-look="chip"] { gap:6px; min-height:44px; padding:8px 16px; border:1px solid var(--ds-selection-control-border); border-radius:99px; background:var(--ds-selection-bg); }
.ds .ds-choice[data-look="chip"] input { width:0; height:18px; border:0; background:transparent; box-shadow:none; }
.ds .ds-choice[data-look="chip"]:has(:focus-visible) { outline:3px solid var(--ds-selection-focus); outline-offset:3px; }
.ds .ds-choice[data-look="chip"]:has(:checked) { padding-left:12px; border-color:var(--ds-selection-accent); background:var(--ds-selection-accent); color:var(--ds-selection-on-accent); }
.ds .ds-choice[data-look="chip"] input:checked { width:18px; background:transparent; }
.ds .ds-choice[data-look="chip"] input[type="checkbox"]:checked::after { left:6px; top:1px; border-color:var(--ds-selection-on-accent); }
.ds .ds-choice[data-look="list"] { width:100%; flex-direction:row-reverse; justify-content:space-between; min-height:52px; padding:12px 4px; border-block:1px solid var(--ds-selection-border); }
.ds .ds-radio-group:has(> .ds-choice[data-look="list"]) .ds-choice + .ds-choice { border-top:0; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) { display:flex; flex-wrap:wrap; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) > legend { width:100%; }
.ds .ds-choice[data-look="segment"] { position:relative; gap:6px; min-height:44px; margin:0; padding:10px 18px; border:1px solid var(--ds-selection-control-border); background:var(--ds-selection-bg); }
.ds .ds-choice[data-look="segment"] + .ds-choice[data-look="segment"] { margin-left:-1px; }
.ds .ds-choice[data-look="segment"]:first-of-type { border-radius:12px 0 0 12px; }
.ds .ds-choice[data-look="segment"]:last-of-type { border-radius:0 12px 12px 0; }
.ds .ds-choice[data-look="segment"] input { position:absolute; inset:0; width:100%; height:100%; opacity:0; }
.ds .ds-choice[data-look="segment"]:has(:checked) { z-index:1; border-color:var(--ds-selection-accent); background:var(--ds-selection-accent); color:var(--ds-selection-on-accent); font-weight:600; }
.ds .ds-choice[data-look="segment"]:has(:checked)::before { content:'✓'; content:'✓' / ''; }
.ds .ds-choice[data-look="segment"]:has(:focus-visible) { z-index:2; outline:3px solid var(--ds-selection-focus); outline-offset:2px; }
.ds .ds-choice[data-look="text"] .ds-switch { width:64px; height:30px; }
.ds .ds-choice[data-look="text"] .ds-switch::before { width:22px; height:22px; top:2.5px; left:3px; }
.ds .ds-choice[data-look="text"] .ds-switch:checked::before { left:36px; }
.ds .ds-choice[data-look="text"] input.ds-switch::after,.ds .ds-choice[data-look="text"] input.ds-switch:checked::after { content:'끔'; content:'끔' / ''; position:absolute; top:50%; left:auto; right:9px; width:auto; height:auto; border:0; transform:translateY(-50%); color:var(--ds-selection-muted); font-size:11px; font-weight:700; line-height:1; }
.ds .ds-choice[data-look="text"] input.ds-switch:checked::after { content:'켬'; content:'켬' / ''; left:10px; right:auto; color:var(--ds-selection-on-accent); }
.ds .ds-choice[data-look]:has(:disabled) input:disabled { background:var(--ds-selection-disabled); border-color:var(--ds-selection-border); box-shadow:none; }
.ds .ds-choice[data-look]:has(:disabled) input:disabled::after { border-color:var(--ds-selection-muted); color:var(--ds-selection-muted); }
.ds .ds-choice[data-look]:has(:disabled) input:is([type="radio"],:indeterminate):disabled::after { background:var(--ds-selection-muted); }
.ds .ds-choice[data-look]:has(:disabled) input.ds-switch:disabled::before { background:var(--ds-selection-muted); box-shadow:none; }
.ds .ds-choice:is([data-look="chip"],[data-look="segment"],[data-look="card"]):has(:disabled) { border-color:var(--ds-selection-border); background:var(--ds-selection-disabled); color:var(--ds-selection-muted); box-shadow:none; }

